import React, { useState, useEffect } from 'react';

/**
 * Component to display an animated 'Hello World' message centered on the screen.
 * The animation cycles through different greetings.
 */
const AnimatedHelloWorld: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [message, setMessage] = useState('Hello World');
  const [animationStep, setAnimationStep] = useState(0);

  // Define the sequence of messages
  const greetings = ['Hello World', '👋 Hello World', '✨ Hello World ✨', '🚀 Hello World 🚀'];

  // Effect to handle the animation cycle when visible
  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;
    if (isVisible) {
      interval = setInterval(() => {
        setAnimationStep(prevStep => (prevStep + 1) % greetings.length);
        setMessage(greetings[prevStep + 1] || greetings[0]);
      }, 1000); // Change message every 1 second
    } else {
      // Clear interval if not visible
      if (interval) clearInterval(interval);
    }

    // Cleanup function
    return () => { if (interval) clearInterval(interval); };
  }, [isVisible]);

  // Function to trigger visibility and start animation
  const handleShow = () => {
    setIsVisible(true);
    setAnimationStep(0);
    setMessage(greetings[0]);
  };

  // Function to hide the animation
  const handleHide = () => {
    setIsVisible(false);
  };

  if (!isVisible) {
    return null; // Render nothing if not triggered
  }

  // Inline styles for perfect centering
  const containerStyle: React.CSSProperties = {
    position: 'fixed',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    fontSize: '3rem',
    fontWeight: 'bold',
    color: '#007bff',
    padding: '20px',
    backgroundColor: 'rgba(255, 255, 255, 0.9)',
    borderRadius: '10px',
    boxShadow: '0 4px 15px rgba(0, 0, 0, 0.2)',
    textAlign: 'center',
    transition: 'opacity 0.5s ease-in-out',
    opacity: 1,
    zIndex: 1000,
  };

  return (
    <div style={containerStyle}>
      {message}
      <div style={{ marginTop: '20px' }}>
        <button onClick={handleHide} style={{ padding: '10px 20px', fontSize: '1rem', cursor: 'pointer' }}>
          Close Animation
        </button>
      </div>
    </div>
  );
};

export default AnimatedHelloWorld;
